const updateIncomeCategory = `-- name: UpdateIncomeCategory :one
UPDATE income_categories SET
    name        = coalesce($1, name),
    description = coalesce($2, description),
    is_hidden   = coalesce($3, is_hidden),
    is_active   = coalesce($4, is_active),
    updated_at  = now()
WHERE group_id = $5 AND id = $6 AND deleted_at IS NULL
RETURNING id, legacy_id, group_id, name, description, is_hidden, is_active, deleted_at, created_at, updated_at
`

type UpdateIncomeCategoryParams struct {
	Name        *string
	Description *string
	IsHidden    *bool
	IsActive    *bool
	GroupID     int64
	ID          int64
}

func (q *Queries) UpdateIncomeCategory(ctx context.Context, arg UpdateIncomeCategoryParams) (IncomeCategory, error) {
	row := q.db.QueryRow(ctx, updateIncomeCategory,
		arg.Name,
		arg.Description,
		arg.IsHidden,
		arg.IsActive,
		arg.GroupID,
		arg.ID,
	)
	var i IncomeCategory
	err := row.Scan(
		&i.ID,
		&i.LegacyID,
		&i.GroupID,
		&i.Name,
		&i.Description,
		&i.IsHidden,
		&i.IsActive,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const voidDeposit = `-- name: VoidDeposit :execrows
UPDATE deposits SET voided_at = now(), voided_by = $3
WHERE group_id = $1 AND id = $2 AND voided_at IS NULL
`

type VoidDepositParams struct {
	GroupID  int64
	ID       int64
	VoidedBy *int64
}

func (q *Queries) VoidDeposit(ctx context.Context, arg VoidDepositParams) (int64, error) {
	result, err := q.db.Exec(ctx, voidDeposit, arg.GroupID, arg.ID, arg.VoidedBy)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const voidDepositEntries = `-- name: VoidDepositEntries :exec
UPDATE account_entries SET voided_at = now() WHERE deposit_id = $1 AND voided_at IS NULL
`

func (q *Queries) VoidDepositEntries(ctx context.Context, depositID *int64) error {
	_, err := q.db.Exec(ctx, voidDepositEntries, depositID)
	return err
}

const voidDepositLedger = `-- name: VoidDepositLedger :exec
UPDATE ledger_entries SET voided_at = now() WHERE deposit_id = $1 AND voided_at IS NULL
`

func (q *Queries) VoidDepositLedger(ctx context.Context, depositID *int64) error {
	_, err := q.db.Exec(ctx, voidDepositLedger, depositID)
	return err
}
